input.proposed_solution:
Add migration 004 that drops users.legacy_id, and stop selecting and mapping it in src/users.js. The column was only used by the v1 API, which was removed in March; nothing reads it anymore.

Patch (already applied in the repository snapshot):
```diff
--- /dev/null
+++ b/migrations/004_drop_legacy_id.sql
@@ -0,0 +1,2 @@
+-- 004: drop users.legacy_id (v1 API was removed)
+ALTER TABLE users DROP COLUMN legacy_id;
--- a/src/users.js
+++ b/src/users.js
@@ -2,10 +2,10 @@

 /**
  * Map a database row to the API user object.
- * @param {{ id: number, email: string, name: string, legacy_id: string | null }} row
+ * @param {{ id: number, email: string, name: string }} row
  */
 export function toApiUser(row) {
-  return { id: row.id, email: row.email, name: row.name, legacyId: row.legacy_id };
+  return { id: row.id, email: row.email, name: row.name };
 }

-export const SELECT_USER = "SELECT id, email, name, legacy_id FROM users WHERE id = ?";
+export const SELECT_USER = "SELECT id, email, name FROM users WHERE id = ?";
--- a/test/users.test.js
+++ b/test/users.test.js
@@ -3,5 +3,5 @@
 import { toApiUser } from "../src/users.js";

 test("maps row", () => {
-  assert.deepEqual(toApiUser({ id: 1, email: "a@x", name: "A", legacy_id: null }), { id: 1, email: "a@x", name: "A", legacyId: null });
+  assert.deepEqual(toApiUser({ id: 1, email: "a@x", name: "A" }), { id: 1, email: "a@x", name: "A" });
 });
```
